  const dbPath = paths.projectMemoryDb(fs.realpathSync(root));
  const localFile = paths.projectSettingsLocal(root);
  const local = readJson(localFile, {}) ?? {};
  local.env = { ...local.env, CLAUDE_FLOW_DB_PATH: dbPath };
